	    LOGGER.info("handling RemoveDatasetsFromBIQueryEvent " );
	
	    BIQuery parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, removeFrom.getDataSetId());
	    
	    parentEntity.getDatasets().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
